    44	    const url = `https://app.ticketmaster.com/discovery/v2/events.json?apikey=${TICKETMASTER_API_KEY}&city=${city}&countryCode=SE&size=50&sort=date,asc`;
    45	    const response = await axios.get(url, { timeout: 15000 });
    46	    
    47	    if (response.data?._embedded?.events) {
    48	      results.ticketmaster.events = response.data._embedded.events.map(ev => ({
    49	        id: ev.id,
    50	        title: ev.name,
    51	        date: ev.dates?.start?.localDate || '',
    52	        time: ev.dates?.start?.localTime ? ev.dates.start.localTime.substring(0, 5) : '',
    53	        venue: ev._embedded?.venues?.[0]?.name || 'Unknown',
    54	        area: ev._embedded?.venues?.[0]?.city?.name || city,
    55	        source: 'ticketmaster',
    56	        imageUrl: ev.images?.[0]?.url || null,
    57	      }));
    58	      results.ticketmaster.count = results.ticketmaster.events.length;
    59	    }
    60	  } catch (e) {
    61	    console.log('[debug] Ticketmaster:', e.message);
    62	  }
    63	  
    64	  // Kulturhuset
