    66	    const esResp = await axios.post(
    67	      'https://elastic.kulturhusetstadsteatern.se/khst-events/_search',
    68	      { size: 20, query: { bool: { must: [{ range: { tixStartDate: { gte: 'now' } } }] } }, sort: [{ tixStartDate: { order: 'asc' } }] },
    69	      { timeout: 10000, headers: { 'Content-Type': 'application/json' } }
    70	    );
