    86	/**
    87	 * Health check with explicit freshness data
    88	 */
    89	async function handleHealth(req, res) {
    90	  let ingestionStatus = { supabase: supabase ? 'connected' : 'disconnected' };
    91	  
    92	  if (supabase) {
    93	    try {
    94	      // Get latest ingestion log
    95	      const { data: latestRun } = await supabase
    96	        .from('ingestion_logs')
    97	        .select('source, action, timestamp')
    98	        .order('timestamp', { ascending: false })
    99	        .limit(1);
   100	      
   101	      // Get event timestamps
   102	      const { data: eventTimes } = await supabase
   103	        .from('events')
   104	        .select('created_at, updated_at, start_time')
   105	        .eq('status', 'published')
   106	        .order('start_time', { ascending: false })
   107	        .limit(1);
   108	      
   109	      // Get events last 24h
   110	      const last24h = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
   111	      const { count: events24h } = await supabase
   112	        .from('events')
   113	        .select('id', { count: 'exact', head: true })
   114	        .eq('status', 'published')
   115	        .gte('start_time', last24h);
   116	      
   117	      // Get active sources
   118	      const now = new Date().toISOString();
   119	      const { data: activeSources } = await supabase
   120	        .from('events')
   121	        .select('source')
   122	        .eq('status', 'published')
   123	        .gte('start_time', now);
   124	      
   125	      ingestionStatus = {
   126	        supabase: 'connected',
   127	        last_ingestion_run: latestRun?.[0]?.timestamp || null,
   128	        events_last_24h: events24h || 0,
   129	        newest_event: eventTimes?.[0]?.start_time || null,
   130	        newest_updated: eventTimes?.[0]?.updated_at || null,
   131	        oldest_event: null, // Would need separate query
   132	        active_sources: [...new Set((activeSources || []).map(e => e.source))],
   133	        active_sources_count: [...new Set((activeSources || []).map(e => e.source))].length,
   134	      };
   135	    } catch (err) {
   136	      ingestionStatus.supabase = 'error';
   137	      ingestionStatus.error = err.message;
   138	    }
   139	  }
   140	  
   141	  res.writeHead(200, { 'Content-Type': 'application/json' });
   142	  res.end(JSON.stringify({ 
   143	    status: 'ok', 
   144	    timestamp: new Date().toISOString(),
   145	    ticketmasterKey: TICKETMASTER_API_KEY ? 'configured' : 'missing',
   146	    ingestion: ingestionStatus
   147	  }));
   148	}
