   150	/**
   151	 * PRIMARY: Fetch events from Supabase with full metadata
   152	 */
   153	async function handleSupabaseEvents(req, res) {
   154	  if (!supabase) {
   155	    res.writeHead(503, { 'Content-Type': 'application/json' });
   156	    res.end(JSON.stringify({ error: 'Supabase not configured', data_source: 'none' }));
   157	    return;
   158	  }
   159	
   160	  const url = new URL(req.url, `http://localhost:${PORT}`);
   161	  const city = url.searchParams.get('city') || 'Stockholm';
   162	  const days = parseInt(url.searchParams.get('days') || '365');
   163	  const limit = parseInt(url.searchParams.get('limit') || '100');
   164	  const source = url.searchParams.get('source') || null;
   165	
   166	  try {
   167	    const now = new Date();
   168	    const startDate = now.toISOString();
   169	    const endDate = new Date(now.getTime() + days * 24 * 60 * 60 * 1000).toISOString();
   170	    const last24h = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();
   171	
   172	    // Get ingestion stats
   173	    let ingestionStats = null;
   174	    try {
   175	      const { data: logs } = await supabase
   176	        .from('ingestion_logs')
   177	        .select('source, action, timestamp')
   178	        .gte('timestamp', last24h)
   179	        .order('timestamp', { ascending: false });
   180	      
   181	      if (logs?.length) {
   182	        const bySource = {};
   183	        logs.forEach(log => {
   184	          bySource[log.source] = bySource[log.source] || { inserted: 0, updated: 0 };
   185	          bySource[log.source][log.action]++;
   186	        });
   187	        ingestionStats = { events_last_24h: logs.length, by_source: bySource, last_run: logs[0].timestamp };
   188	      }
   189	    } catch (e) {
   190	      console.warn('[api] Could not fetch ingestion stats:', e.message);
   191	    }
   192	
   193	    // Get total count
   194	    const { count: totalCount } = await supabase
   195	      .from('events')
   196	      .select('id', { count: 'exact', head: true })
   197	      .eq('status', 'published');
   198	
   199	    // Get source counts
   200	    const { data: sourceCounts } = await supabase
   201	      .from('events')
   202	      .select('source')
   203	      .eq('status', 'published')
   204	      .gte('start_time', startDate)
   205	      .lte('start_time', endDate);
   206	    
   207	    const sourceCountsMap = {};
   208	    (sourceCounts || []).forEach(e => {
   209	      sourceCountsMap[e.source] = (sourceCountsMap[e.source] || 0) + 1;
   210	    });
   211	
   212	    // Get active sources
   213	    const { data: activeSourcesData } = await supabase
   214	      .from('events')
   215	      .select('source')
   216	      .eq('status', 'published')
   217	      .gte('start_time', startDate);
   218	    
   219	    const activeSourceKeys = [...new Set((activeSourcesData || []).map(e => e.source))];
   220	
   221	    // Build query
   222	    let query = supabase
   223	      .from('events')
   224	      .select(`id, title_en, title_sv, description_en, description_sv, start_time, end_time, source, venue_id, venues:venue_id(name, address), category_slug, is_free, price_min_sek, price_max_sek, ticket_url, image_url`)
   225	      .gte('start_time', startDate)
   226	      .lte('start_time', endDate)
   227	      .eq('status', 'published')
   228	      .order('start_time', { ascending: true })
   229	      .limit(limit);
   230	
   231	    if (source) query = query.eq('source', source);
   232	
   233	    const { data: events, error } = await query;
   234	
   235	    if (error) {
   236	      res.writeHead(500, { 'Content-Type': 'application/json' });
   237	      res.end(JSON.stringify({ error: error.message, data_source: 'supabase' }));
   238	      return;
   239	    }
   240	
   241	    // UNIFIED EVENT SHAPE
   242	    const transformedEvents = (events || []).map(ev => ({
   243	      id: ev.id,
   244	      title: ev.title_en || ev.title_sv || 'Untitled',
   245	      date: ev.start_time ? ev.start_time.split('T')[0] : '',
   246	      time: ev.start_time ? ev.start_time.split('T')[1]?.substring(0, 5) : '',
   247	      venue_name: ev.venues?.name || '',
   248	      venue_address: ev.venues?.address || '',
   249	      city: city,
   250	      description: ev.description_en || ev.description_sv || '',
   251	      source: ev.source,
   252	      category_slug: ev.category_slug || 'community',
   253	      is_free: ev.is_free || false,
   254	      price_min: ev.price_min_sek,
   255	      price_max: ev.price_max_sek,
   256	      ticket_url: ev.ticket_url || '',
   257	      image_url: ev.image_url || null,
   258	      // Legacy aliases
   259	      venue: ev.venues?.name || '',
   260	      area: city,
   261	      url: ev.ticket_url || '',
   262	      category: ev.category_slug || 'culture',
   263	      isFree: ev.is_free || false,
   264	      priceMin: ev.price_min_sek,
   265	      priceMax: ev.price_max_sek,
   266	      imageUrl: ev.image_url,
   267	    }));
   268	
   269	    // Sources for dropdown - ONLY canonical
   270	    const sources = filterCanonicalSources(activeSourceKeys);
   271	
   272	    res.writeHead(200, { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' });
   273	    res.end(JSON.stringify({
   274	      data_source: 'supabase',
   275	      fallback_used: false,
   276	      timestamp: new Date().toISOString(),
   277	      ingestion_stats: ingestionStats,
   278	      total_published_events: totalCount || 0,
   279	      source_counts: sourceCountsMap,
   280	      sources: sources,
   281	      events: transformedEvents,
   282	      count: transformedEvents.length,
   283	      query_params: { city, days, limit, source }
   284	    }));
   285	  } catch (err) {
   286	    console.error('[api] Supabase fetch error:', err);
   287	    res.writeHead(500, { 'Content-Type': 'application/json' });
   288	    res.end(JSON.stringify({ error: err.message, data_source: 'supabase' }));
   289	  }
   290	}
